1	/**
2	 * pyruntime.mjs — the top-level behaviour CPython supplies around `main()`.
3	 *
4	 * Three exit paths have to be reproduced:
5	 *
6	 *   * `SystemExit`  -> exit with its code, nothing extra on stderr
7	 *   * any other exception -> traceback on stderr, exit 1
8	 *   * clean return -> exit 0
9	 *
10	 * The reference program is a PyInstaller bundle, so an unhandled exception is
11	 * followed by PyInstaller's own `[PYI-<pid>:ERROR]` line. Both are emitted here
12	 * so stderr matches as closely as a non-Python process can manage.
13	 */
14	
15	import { SystemExit, PyError } from './pyerrors.mjs';
16	import { writeStderr } from './pyio.mjs';
17	
18	/**
19	 * Renders a CPython traceback from a static frame list, innermost last.
20	 * Each frame is `{ file, line, name }`.
21	 */
22	export function formatTraceback(frames, error) {
23	  let out = 'Traceback (most recent call last):\n';
24	  for (const frame of frames) {
25	    out += `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
26	  }
27	  const name = error instanceof PyError ? error.pyName : error.name || 'Exception';
28	  const message = error instanceof PyError ? error.toPyString() : error.message;
29	  out += message ? `${name}: ${message}\n` : `${name}\n`;
30	  return out;
31	}
32	
33	/**
34	 * Runs `main` under CPython's exit semantics.
35	 *
36	 * `options.traceback` supplies the frame list for an unhandled exception, and
37	 * `options.script` is the module name PyInstaller reports.
38	 */
39	export function runMain(main, options = {}) {
40	  const frames = options.traceback || [];
41	  const script = options.script || 'test7';
42	
43	  try {
44	    main();
45	  } catch (err) {
46	    if (err instanceof SystemExit) {
47	      process.exitCode = typeof err.code === 'number' ? err.code : err.code ? 1 : 0;
48	      return;
49	    }
50	    writeStderr(formatTraceback(frames, err));
51	    writeStderr(`[PYI-${process.pid}:ERROR] Failed to execute script '${script}' due to unhandled exception!\n`);
52	    process.exitCode = 1;
53	  }
54	}
